        "code": "import math\n\nclass BSMGreeksEngine:\n    @staticmethod\n    def norm_pdf(x):\n        return (1.0 / math.sqrt(2.0 * math.pi)) * math.exp(-0.5 * (x ** 2))\n\n    @staticmethod\n    def norm_cdf(x):\n        return (1.0 + math.erf(x / math.sqrt(2.0))) / 2.0\n\n    @classmethod\n    def calculate_greeks(cls, s, k, t, r, sigma):\n        if t <= 0:\n            return {\"delta\": 0.0, \"gamma\": 0.0, \"vega\": 0.0, \"theta\": 0.0, \"vanna\": 0.0}\n            \n        d1 = (math.log(s / k) + (r + 0.5 * (sigma ** 2)) * t) / (sigma * math.sqrt(t))\n        d2 = d1 - sigma * math.sqrt(t)\n        pdf_d1 = cls.norm_pdf(d1)\n        \n        delta_call = cls.norm_cdf(d1)\n        gamma = pdf_d1 / (s * sigma * math.sqrt(t))\n        vega = s * math.sqrt(t) * pdf_d1 * 0.01 # 1% vol change\n        theta = (-(s * pdf_d1 * sigma) / (2 * math.sqrt(t)) - r * k * math.exp(-r * t) * cls.norm_cdf(d2)) / 365.0\n        vanna = -pdf_d1 * d2 / sigma\n        \n        return {\n            \"delta\": round(delta_call, 4),\n            \"gamma\": round(gamma, 4),\n            \"vega\": round(vega, 4),\n            \"theta\": round(theta, 4),\n            \"vanna\": round(vanna, 4)\n        }\n\ng = BSMGreeksEngine.calculate_greeks(s=100.0, k=100.0, t=0.5, r=0.05, sigma=0.20)\nprint(\"At-The-Money Call Greeks (6-month):\")\nprint(f\"Delta: {g['delta']} | Gamma: {g['gamma']}\")\nprint(f\"Vega (per 1% vol): ${g['vega']} | Theta (per day): ${g['theta']}\")\nprint(f\"Vanna (cross-Greek): {g['vanna']}\")",
