        "code": "import math\n\nclass DeflatedSharpeRatioEngine:\n    @staticmethod\n    def norm_cdf(x):\n        return (1.0 + math.erf(x / math.sqrt(2.0))) / 2.0\n\n    @classmethod\n    def compute_dsr(cls, observed_sr, t_samples, n_trials, skewness=0.0, kurtosis=3.0, var_trials=1.0):\n        # 1. Variance of the Sharpe ratio estimator\n        excess_kurt = kurtosis - 3.0\n        sr_var = (1.0 - skewness * observed_sr + ((kurtosis - 1.0) / 4.0) * (observed_sr ** 2)) / max(1, t_samples - 1)\n        sr_std = math.sqrt(max(1e-6, sr_var))\n        \n        # 2. Expected maximum Sharpe under null hypothesis (Euler constant = 0.5772)\n        if n_trials <= 1:\n            sr_benchmark = 0.0\n        else:\n            ln_n = math.log(n_trials)\n            z = math.sqrt(2.0 * ln_n)\n            sr_benchmark = (z + (0.5772156649 / z)) * math.sqrt(var_trials)\n            \n        # 3. DSR z-statistic\n        z_dsr = (observed_sr - sr_benchmark) / sr_std\n        dsr_prob = cls.norm_cdf(z_dsr)\n        \n        return {\n            \"observed_sr\": observed_sr,\n            \"benchmark_sr\": round(sr_benchmark, 3),\n            \"dsr_z_stat\": round(z_dsr, 3),\n            \"dsr_probability\": round(dsr_prob, 4),\n            \"is_significant\": dsr_prob >= 0.95\n        }\n\n# Scenario: Strategy with Sharpe 2.5 on 252 days of data\n# Case A: First attempt (N=1)\nres_a = DeflatedSharpeRatioEngine.compute_dsr(observed_sr=2.5, t_samples=252, n_trials=1)\n# Case B: Best out of 500 attempted model variations (N=500)\nres_b = DeflatedSharpeRatioEngine.compute_dsr(observed_sr=2.5, t_samples=252, n_trials=500)\n\nprint(f\"Sharpe 2.5 (1 Trial):   DSR = {res_a['dsr_probability']} -> Status: {'APPROVED' if res_a['is_significant'] else 'REJECTED'}\")\nprint(f\"Sharpe 2.5 (500 Trials): DSR = {res_b['dsr_probability']} -> Status: {'APPROVED' if res_b['is_significant'] else 'REJECTED'}\")",
